style.css:
@-moz-document domain("deepseek.com") {
/* Root variables - override all blue to pink */
    :root {
        --ds-primary: #ff69b4 !important;
        --ds-primary-hover: #ff1493 !important;
        --ds-primary-light: #ff85c1 !important;
        --color-primary: #ff69b4 !important;
        --color-primary-hover: #ff1493 !important;
        --blue-500: #ff69b4 !important;
        --blue-600: #ff1493 !important;
    }
    
    /* Target ALL buttons and make them pink instead of blue */
    button,
    .btn,
    .button,
    [role="button"],
    [class*="btn"],
    [class*="button"],
    [class*="primary"],
    [class*="submit"],
    [type="submit"],
    [type="button"] {
        background-color: #ff69b4 !important;
        border-color: #ff69b4 !important;
        color: white !important;
    }
    
    /* Button hover states */
    button:hover,
    .btn:hover,
    .button:hover,
    [role="button"]:hover,
    [class*="btn"]:hover,
    [class*="button"]:hover {
        background-color: #ff1493 !important;
        border-color: #ff1493 !important;
    }
    
    /* Specific button types that might be blue */
    .bg-blue-500,
    .bg-blue-600,
    .bg-blue-700,
    .bg-primary,
    [class*="bg-blue"],
    [class*="bg-primary"] {
        background-color: #ff69b4 !important;
    }
    
    /* Text that is blue (links, icons) */
    .text-blue-500,
    .text-blue-600,
    .text-primary,
    [class*="text-blue"],
    a:not([class*="text-white"]) {
        color: #ff69b4 !important;
    }
    
    /* Blue borders */
    .border-blue-500,
    .border-primary,
    [class*="border-blue"] {
        border-color: #ff69b4 !important;
    }
    
    /* Focus rings (replace blue with pink) */
    :focus {
        box-shadow: 0 0 0 2px rgba(255, 105, 180, 0.3) !important;
        border-color: #ff69b4 !important;
    }
    
    /* Selection highlight */
    ::selection {
        background-color: rgba(255, 105, 180, 0.3) !important;
    }
    
    /* Dark background - keep default dark mode */
    body,
    .dark,
    [data-theme="dark"],
    .bg-gray-900,
    .bg-black,
    .bg-dark {
        background-color: #0a0a0a !important;
    }
    
    /* Logo replacement - Hide original and add GIF */
    /* Find the logo container/image */
    img[alt*="DeepSeek"],
    img[alt*="deepseek"],
    [class*="logo"] img,
    [class*="Logo"] img,
    .logo-container img,
    .navbar-logo img,
    header img:first-child {
        content: url('https://i.pinimg.com/originals/e0/e3/64/e0e364075f88ce85d355c8218199ebc8.gif') !important;
        opacity: 0 !important;
    }
    
    /* Alternative method - replace via pseudo-element */
    [class*="logo"],
    [class*="Logo"],
    .logo-container,
    .navbar-brand {
        position: relative !important;
    }
    
    [class*="logo"]::before,
    [class*="Logo"]::before,
    .logo-container::before,
    .navbar-brand::before {
        content: '' !important;
        position: absolute !important;
        top: 0 !important;
        left: 0 !important;
        width: 100% !important;
        height: 100% !important;
        background-image: url('https://i.pinimg.com/originals/e0/e3/64/e0e364075f88ce85d355c8218199ebc8.gif') !important;
        background-size: contain !important;
        background-repeat: no-repeat !important;
        background-position: center !important;
        z-index: 10 !important;
        pointer-events: none !important;
    }
    
    /* Ensure text remains readable on dark background */
    body, p, span, div, label, h1, h2, h3, h4, h5, h6 {
        color: #e5e5e5 !important;
    }
    
    /* Chat interface specific elements */
    [class*="chat"],
    [class*="message"],
    .message-bubble {
        background-color: #1a1a1a !important;
    }
    
    /* Input fields */
    input, textarea, select {
        background-color: #1a1a1a !important;
        border-color: #ff69b4 !important;
        color: #e5e5e5 !important;
    }
    
    input:focus, textarea:focus {
        border-color: #ff1493 !important;
    }
    
    /* Scrollbar */
    ::-webkit-scrollbar-thumb {
        background-color: #ff69b4 !important;
    }
    
    ::-webkit-scrollbar-thumb:hover {
        background-color: #ff1493 !important;
    }
    
    /* Loading spinners if they're blue */
    [class*="spinner"],
    [class*="loader"] {
        border-top-color: #ff69b4 !important;
    }
}
